% script SICT with PrEP 
% 21 august 2023
%% Numerically
clear all;
b = 1/2;
[paramTab,mu,vecAlphas] = sampleParameters_v2(false,false,true,false,b);

prm = paramTab{1};
Y0 = ones(7,1); tspan = 0:1:1000;
options = odeset('RelTol',1e-5,'Stats','on');%,'OutputFcn',@odeplot);
prm.p = 0.1; prm.zeta=0.3;prm.eta=3; rho=0.4;
[ts,Ys] = ode45(@(t,Y) ODE_SICTPrEP(t,Y,b,prm.betaI,prm.betaC,prm.sigma,prm.theta,prm.p,prm.zeta,prm.eta,mu,rho,'frequency'), tspan,Y0,options);
popEnd = Ys(end,:)
Nnum   = sum(popEnd); %b/mu

R0 = (1-prm.p)*(prm.betaI*(mu+rho+prm.theta)+prm.betaC*prm.sigma)./((mu+rho+prm.sigma)*(mu+rho+prm.theta)) + prm.p*(1-prm.zeta)*(prm.betaI*(prm.eta+mu+prm.theta)+prm.betaC*prm.sigma)./((prm.eta+mu+prm.sigma)*(prm.eta+mu+prm.theta))

R01 = (1-prm.p)*(prm.betaI*(mu+rho+prm.theta)+prm.betaC*prm.sigma)./((mu+rho+prm.sigma)*(mu+rho+prm.theta));
R02 = prm.p*(1-prm.zeta)*(prm.betaI*(prm.eta+mu+prm.theta)+prm.betaC*prm.sigma)./((prm.eta+mu+prm.sigma)*(prm.eta+mu+prm.theta));

R0 = R01+R02;

b/(mu*R01)*prm.p*(1-prm.zeta)
b/(mu*R02)*(1-prm.p)*prm.zeta
popEnd

sum(popEnd([2,3,5,6,7]))
b/mu*(1-1/R0)

[RH,LambdaH,~] = Rp_SICTP(prm.betaI,prm.betaC,prm.theta,...
    prm.sigma,prm.zeta,prm.eta,prm.p,mu,b,rho);
SES_H = b*(1-prm.p)./(LambdaH+mu);
PES_H = prm.p*b./(LambdaH*(1-prm.zeta)+mu);

%% Analytically
clear all;
syms b betaI betaC sigma theta0 p zeta eta mu rho lambda
syms S I C P Ip Cp T
theta  = theta0+rho;
N = b/mu;
%lambda = (betaI*(I+Ip)+betaC*(C+Cp))/N;

dS  = (1-p)*b - lambda*S-mu*S;
dI  = lambda*S - (sigma+rho+mu)*I;
dC  = sigma*I - (theta+mu)*C;
dP  = p*b - (1-zeta)*lambda*P - mu*P;
dIp = (1-zeta)*lambda*P - (sigma+eta+mu)*Ip;
dCp = sigma*Ip - (theta0+eta+mu)*Cp;
dT  = rho*I+theta*C + eta*Ip + (theta0+eta)*Cp - mu*T;

eqn1 = dS==0;
eqn2 = dI==0;
eqn3 = dC==0;
eqn4 = dP==0;
eqn5 = dIp==0;
eqn6 = dCp==0;
eqn7 = dT==0;
%eqns = [dS==0;dI==0;dC==0;dP==0;dIp==0;dCp==0;dT==0];
sol = solve([eqn1,eqn2,eqn3,eqn4,eqn5,eqn6,eqn7],[S,I,C,P,Ip,Cp,T]);

%----------
eqn1 = I  == -(b*lambda*(p - 1))/((lambda + mu)*(mu + rho + sigma));
eqn2 = Ip == -(b*lambda*p*(zeta - 1))/((lambda + mu - lambda*zeta)*(eta + mu + sigma));
eqn3 = C  == -(b*lambda*sigma*(p - 1))/((lambda + mu)*(mu + rho + sigma)*(mu + rho + theta0));
eqn4 = Cp == -(b*lambda*p*sigma*(zeta - 1))/((lambda + mu - lambda*zeta)*(eta + mu + sigma)*(eta + mu + theta0));
eqn5 = lambda == (betaI*(IES+IpES)+betaC*(CES+CpES))*mu/b;
sol = solve([eqn1,eqn2,eqn3,eqn4,eqn5],[I,Ip,C,Cp,lambda])
%---------
a = (1-p)./(mu+rho+sigma);
b = p*(1-zeta)./(eta+mu+sigma);
c = (1-p)./((sigma+rho+mu)*(theta0+rho+mu));
d = p*(1-zeta)./((eta+mu+sigma)*(eta+mu+theta0));

I_p_Ip = b*lambda*(a/(lambda+mu)+b/(lambda+mu-lambda*zeta));
C_p_Cp = b*lambda*sigma*(c/(lambda+mu)+d/(lambda+mu-lambda*zeta));
simplify(I+Ip - I_p_Ip)
simplify(C+Cp - C_p_Cp)

eq0 = lambda == (betaI*I_p_Ip+betaC*C_p_Cp)*mu/b
solve(eq0,lambda)
