param.eta = eta; param.p=p; param.zeta=zeta;

vecC = linspace(-0.1,0.15,500);
i=0; rhohat=[]; Rrho=[]; Ptot=[]; Pun=[];
for c=vecC
    i=i+1;
    C_c = @(rho)-U_SICTP(param,mu,b,rho,c,f); %attention, individus sous prep pas inclus dans P
    rhohat(i) = fmincon(C_c,0.,[-1;1],[0;alpha]);
    [Rrho(i),~,~,Ptot(i),Pun(i)] = Rp_SICTP(betaI,betaC,theta0,gamma0,sigma,zeta,eta,p,mu,b,rhohat(i));
end

figure(1)
hold on
plot(vecC,rhohat)
xlabel('$c$','Interpreter','latex')
ylabel('$\hat\rho$','Interpreter','latex')

tabrecap = [vecC;rhohat;Rrho;Ptot;Pun]';

tabrecap(tabrecap(:,2)<0.0001,2)=0;
tabrecap(tabrecap(:,4)<0.0001,4)=0;
tabrecap(tabrecap(:,5)<0.0001,5)=0;



